return ['domain'=>'press-permit-core|| n % 10 == 6 || n % 10 == 9);|| n % 10 == 6 || n % 10 == 9);:','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:58+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'Ang PublishPress Permissions ay nagbibigay-daan sa iyo na payagan o tanggihan ang pag-access sa mga post, pahina, kategorya, tag at iba pa.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'I-edit ang Tag para sa Lahat ng Uri ng Post','Edit Tag for Posts'=>'I-edit ang Tag para sa mga Post','Advanced Custom Fields'=>'Advanced Custom Fields','Control front-end access to Field Groups with advanced permission management.'=>'Kontrolin ang access sa front-end sa Field Groups gamit ang advanced permission management.','Control access to Field Groups'=>'Kontrolin ang access sa mga Field Groups','Front-end visibility restrictions'=>'Mga paghihigpit sa visibility sa harapang bahagi','Integration with permission groups'=>'Pagsasama sa mga grupo ng pahintulot','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Pagkakatugma sa Edit Permissions sa Beaver Builder.','Beaver editor integration'=>'Pagsasama ng Beaver editor','Widget-level permission controls'=>'Mga kontrol ng pahintulot sa antas ng widget','Template access restrictions'=>'Mga paghihigpit sa access ng template','bbPress Forums'=>'bbPress Forums','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Mga pahintulot na tiyak sa forum para sa bbPress na may detalyadong kontrol sa access at pakikilahok sa forum.','Forum-specific permissions'=>'Mga pahintulot na tiyak sa forum','Topic creation restrictions'=>'Mga limitasyon sa paglikha ng paksa','Forum access controls'=>'Mga kontrol sa pag-access ng forum','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Magtalaga ng mga pahintulot sa post at termino sa mga grupo ng BuddyPress para sa pinahusay na kontrol sa nilalaman.','Assign post permissions to BuddyPress groups'=>'Italaga ang mga pahintulot sa post sa mga grupo ng BuddyPress','Assign term permissions to BuddyPress groups'=>'Italaga ang mga pahintulot sa term sa mga grupo ng BuddyPress','Group-based content permissions'=>'Mga pahintulot sa nilalaman batay sa grupo','CMS Tree View'=>'CMS Tree View','Compatibility with Edit Permissions in CMS Tree View.'=>'Pagkakatugma sa Pag-edit ng mga Pahintulot sa CMS Tree View.','Permission-aware tree view'=>'Tree view na may kaalaman sa pahintulot','Hierarchical content controls'=>'Hierarchical na kontrol sa nilalaman','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Pagkakatugma sa Pag-edit ng mga Pahintulot sa Elementor.','Elementor editor integration'=>'Pagsasama ng editor ng Elementor','The Events Calendar'=>'The Events Calendar','Apply permission controls to events and event-related content.'=>'Mag-apply ng mga kontrol sa pahintulot sa mga kaganapan at mga nilalaman na may kaugnayan sa kaganapan.','Event post permissions'=>'Mga pahintulot sa post ng kaganapan','Event taxonomy controls'=>'Mga kontrol sa taxonomy ng kaganapan','Nested Pages'=>'Nested Pages','Compatibility with Edit Permissions in Nested Pages.'=>'Pagkakatugma sa Pag-edit ng mga Pahintulot sa Nested Pages.','Permission-aware nested view'=>'Nakatagong tanawin na may pahintulot','Quick edit integration'=>'Pagsasama ng mabilis na pag-edit','PublishPress Statuses'=>'Mga Status ng PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Pagkakatugma sa plugin ng Mga Status ng PublishPress.','Custom status permissions'=>'Mga pahintulot sa pasadyang status','Workflow-specific access controls'=>'Mga kontrol sa pag-access na tiyak sa daloy ng trabaho','Status-based editing capabilities'=>'Mga kakayahan sa pag-edit batay sa status','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'I-filter ang mga resulta ng paghahanap batay sa View Permissions para sa secure na pagtuklas ng nilalaman.','Search result filtering'=>'Pag-filter ng mga resulta ng paghahanap','Permission-aware indexing'=>'Nakatagong pag-index na may pahintulot','Secure content discovery'=>'Ligtas na pagtuklas ng nilalaman','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Pagkakatugma sa pag-filter ng termino ng SearchWP para sa mga advanced na kakayahan sa paghahanap.','Permission-aware search results'=>'Nakatagong mga resulta ng paghahanap na may pahintulot','Term-based filtering'=>'Pag-filter batay sa termino','Advanced search controls'=>'Mga kontrol sa advanced na paghahanap','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Ilapat ang mga kontrol sa pahintulot sa mga produkto ng WooCommerce at mga kategorya ng produkto.','Product permissions'=>'Mga pahintulot sa produkto','Product category controls'=>'Mga kontrol sa kategorya ng produkto','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Suporta sa maraming wika na may pagkakasabay-sabay ng pahintulot sa mga pagsasalin ng nilalaman.','Permission synchronization across translations'=>'Synchronisasyon ng pahintulot sa mga pagsasalin','Language-specific content access'=>'Access sa nilalaman ayon sa wika','Multilingual permission management'=>'Pamamahala ng pahintulot na multilingguwal','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Iwasan ang mga pinigilang post mula sa XML sitemaps upang mapanatili ang wastong SEO indexing.','Sitemap filtering for restricted content'=>'Pag-filter ng sitemap para sa pinigilang nilalaman','Search engine visibility controls'=>'Mga kontrol ng visibility sa search engine','Permission-aware XML sitemaps'=>'Mga XML sitemaps na may kamalayan sa pahintulot','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Kompatibilidad sa YooTheme builder at mga pahintulot ng termino.','Builder interface compatibility'=>'Kompatibilidad ng interface ng builder','Term permission integration'=>'Pagsasama ng pahintulot ng termino','Template access controls'=>'Mga kontrol sa access ng template','Viewing'=>'Pagtingin','Access Circles'=>'Mga Bilog ng Access','Editing Permissions'=>'Pag-edit ng mga Pahintulot','Compatibility Pack'=>'Kompatibilidad ng Pakete','Teaser'=>'Teaser','File Access'=>'Pag-access ng File','Membership'=>'Membership','User Posts'=>'Mga Post ng User','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Ang Visibility Circles at Editorial Circles ay humaharang sa pag-access sa nilalaman na hindi isinulat ng iba pang mga miyembro ng grupo.','Post-specific and category-specific permissions for creation and editing.'=>'Mga pahintulot na tiyak sa post at kategorya para sa paglikha at pag-edit.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Pagsasama sa ACF, bbPress, BuddyPress, Relevanssi, WPML at iba pang mga plugin; pinahusay na suporta para sa Multisite.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Sa front end ng site, ipakita ang teaser text para sa mga unreadable na post sa halip na itago ang mga ito.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Limitahan ang mga direktang kahilingan para sa mga file batay sa access ng gumagamit sa pahina kung saan nakakabit ang file.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'I-customize ang limitasyon sa oras ng access sa pamamagitan ng pag-antala o pag-expire ng membership sa Permission Group.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Awtomatikong lumikha ng isang pahina para sa bawat gumagamit ng tinukoy na mga tungkulin. Tugma sa ilang Team / Staff na mga plugin.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Ang Visibility Circles at Editorial Circles ay humaharang sa pag-access sa nilalaman na hindi isinulat ng iba pang mga miyembro ng grupo. Anumang WP Role, BuddyPress Group o custom Group ay maaaring markahan bilang Circle para sa tinukoy na mga uri ng post.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Sumusuporta sa mga tiyak na pahintulot sa nilalaman para sa pag-edit, pagtatalaga ng termino at pagpili ng magulang na pahina. Sa kumbinasyon ng iba pang mga module, sumusuporta sa mga estado ng workflow, PublishPress at PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Nagdaragdag ng compatibility o integration sa ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, at iba pang mga plugin. I-configure ang anumang BuddyPress Group bilang Permission Group. Para sa multisite, nagbibigay ng network-wide Permission Groups.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Sa front end ng site, palitan ang non-readable na nilalaman ng placeholder text. Maaaring i-enable para sa anumang uri ng post. Nagbibigay ng mga custom filters ngunit walang kinakailangang programming para sa pangunahing paggamit.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'I-filter ang direktang pag-access sa file, batay sa access ng gumagamit sa post(s) kung saan nakakabit ang file. Walang kinakailangang karagdagang configuration. Lumilikha/nagbabago ng .htaccess file sa uploads folder (at sa pangunahing folder para sa multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Pinapayagan ang membership sa Permission Group na may limitasyon sa petsa (naantala at/o naka-iskedyul para sa pag-expire). Simple na UI ng date picker kasabay ng pagpili ng membership sa grupo.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Lumikha o i-synchronize ang mga post upang tumugma sa mga gumagamit. Idinisenyo para sa Team / Staff na mga plugin, ngunit may malawak na potensyal na paggamit.','If you like %s, please leave us a %s rating. Thank you!'=>'Kung gusto mo ang %s, mangyaring iwanan kami ng %s rating. Salamat!','About PublishPress Permissions'=>'Tungkol sa PublishPress Permissions','About'=>'Tungkol','Permissions Documentation'=>'Dokumentasyon ng Mga Pahintulot','Documentation'=>'Dokumentasyon','Contact the PublishPress team'=>'Makipag-ugnayan sa koponan ng PublishPress','Contact'=>'Makipag-ugnayan','Permission Group'=>'Grupo ng Pahintulot','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Mga Tiyak na Pahintulot: ang mga paghihigpit (\'Blocked\') ay may priyoridad sa mga karagdagan (\'Enabled\')','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Mga Tiyak na Pahintulot: walang mga paghihigpit (\'Blocked\') na maaaring ilapat sa mga custom-defined groups','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Magagamit ang karagdagang mga tungkulin para sa {All} at {Anonymous} na metagroups','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Payagan ang {All} at {Anonymous} na mga metagroups na bigyan ng tiyak na mga pahintulot sa pagbabasa para sa pribadong nilalaman','Users who have specific editing permissions for a post or attachment can also delete it'=>'Ang mga gumagamit na may tiyak na mga pahintulot sa pag-edit para sa isang post o attachment ay maaari ring burahin ito','Users who have custom editing permissions for an attachment can also delete it'=>'Ang mga gumagamit na may custom na mga pahintulot sa pag-edit para sa isang attachment ay maaari ring burahin ito','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'I-disable ang front end filtering kung ang nakalog-in na gumagamit ay isang content administrator (karaniwang filter upang pilitin ang pagsasama ng mga readable private posts sa get_pages() listing, count ng post, atbp.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'I-disable ang front end filtering para sa lahat ng gumagamit (napapailalim sa limitasyon ng PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Listahan ng mga uri ng post na pinaghihiwalay ng kuwit upang limitahan ang epekto ng PP_UNFILTERED_FRONT at apply_filters(\'presspermit_skip_cap_filtering\')','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Mga Tiyak na Pahintulot: ang mga karagdagan (\'Enabled\') ay hindi nalalapat, hindi maaaring italaga','Don\'t assign or apply specific permissions for the \'post\' type'=>'Huwag italaga o i-apply ang tiyak na mga pahintulot para sa uri ng \'post\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Huwag italaga o i-apply ang tiyak na mga pahintulot para sa uri ng \'page\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Huwag italaga o i-apply ang tiyak na mga pahintulot para sa uri ng \'media\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Huwag italaga o ilapat ang mga tiyak na pahintulot para sa tinukoy na custom post type','Include scheduled posts in the posts query if user can edit them'=>'Isama ang mga nakaiskedyul na post sa query ng mga post kung ang gumagamit ay maaaring i-edit ang mga ito','Don\'t filter term post counts in get_terms() call'=>'Huwag i-filter ang bilang ng term post sa tawag na get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Iwanan ang mga hindi mababasang post sa WP Navigation Menus','Don\'t apply CSS to hide empty Nav Menus'=>'Huwag mag-apply ng CSS upang itago ang mga walang laman na Nav Menus','For legacy Nav Menus, hide empty nav menu div'=>'Para sa mga legacy Nav Menus, itago ang walang laman na div ng nav menu','Leave terms with no readable posts on WP Navigation Menus'=>'Iwanan ang mga term na walang mababasang post sa WP Navigation Menus','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Kapag ang Teaser ay inilapat na may Redirect na enabled, idagdag ang orihinal na url bilang redirect_to argument','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Para sa compatibility ng Teaser, tukuyin ang isang redirect argument na gagamitin sa halip na redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Para sa compatibility ng Teaser, tukuyin ang isang karagdagang redirect argument bukod sa redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Para sa compatibility ng Teaser, hadlangan ang pp_permissions argument mula sa pagdaragdag sa redirects','Filter priority for \'get_pages\' filter (default: 1)'=>'Filter priority para sa \'get_pages\' filter (default: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Huwag isama ang mga readable private pages sa Pages widget o iba pang wp_list_pages() / get_pages() na resulta    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Kung ang ilang mga pahina ay na-suppress mula sa mga resulta ng get_pages(), baguhin ang mga katumbas na post_parent values ng mga child pages sa isang nakikitang ninuno','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Huwag kailanman baguhin ang post_parent value sa set ng resulta ng get_pages(), kahit na ang ilang mga pahina ay na-suppress','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Para sa pagganap, baguhin ang database query ng get_pages() upang ibalik lamang ang isang subset ng mga fields, na hindi kasama ang post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Huwag ilapat ang content teaser sa mga resulta ng get_pages() (iwanang nakatago ang mga unreadable na post)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Kung ang ilang mga termino ay na-suppress mula sa mga resulta ng get_terms(), baguhin ang mga katumbas na parent values ng mga child terms sa isang nakikitang ninuno','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Huwag kailanman baguhin ang parent value sa set ng resulta ng get_terms(), kahit na ang ilang mga termino ay na-suppress','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Itakda ang May-Akda sa kasalukuyang gumagamit kung ang autoset_post_author / autoset_page_author capability ay naitalaga','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Iwanang ang Media Library na may normal na mga pamantayan sa pag-access batay sa kakayahan ng tungkulin ng gumagamit ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'I-accommodate ang mga solusyon sa pag-upload sa front end na nangangailangan ng mga kakayahan sa pag-edit ng pahina para sa async upload request','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Ituring ang media na nakakabit sa mga unregistered post types bilang unattached, upang maiwasan ang hindi tamang at nakakalitong filtering','Attached Files Private setting available'=>'Naka-attach na Mga File Pribadong setting na available','Comma-separated list of mime types to exclude from File Access filtering'=>'Listahan ng mga mime type na pinaghiwalay ng kuwit na ibubukod mula sa pag-filter ng File Access','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Listahan ng mga mime types na pinaghihiwalay ng kuwit upang isama sa File Access filtering (na lumalampas sa iba)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Kapag ang pag-access sa file ay naharang, huwag itakda ang WP_Query 404 / 403 na katangian','HTTP status code to send when file access is blocked'=>'HTTP status code na ipapadala kapag ang pag-access sa file ay naharang','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Sa listahan ng mga Gumagamit, ang mga Permission group sa custom column ay list filter links sa halip na mga link sa pag-edit ng grupo','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'I-unlock ang Permissions > Settings > Core > Admin Back End > \'Itago ang mga non-editable na post\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'Sa loob ng script na async-upload.php, i-filter ang pagkuha ng may-akda ng attachment na kanilang na-upload','Don\'t filter comment display or moderation within wp-admin'=>'Huwag i-filter ang pagpapakita ng komento o moderasyon sa loob ng wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Payagan ang mga Administrators na maidagdag sa Permission Groups, kahit na sila ay hindi limitado','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Kung ang mga propagating permissions ay naitalaga sa isang branch ng pahina, isusulat ang anumang tahasang naitalagang mga pahintulot sa mga sub-pahina','Max number of specific permissions to insert in a single database query (default 1000)'=>'Max na bilang ng mga tiyak na pahintulot na ipapasok sa isang solong database query (default 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Huwag i-tweak ang mga index ng admin menu upang ilagay ang Permissions menu sa ilalim ng Mga Gumagamit','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Huwag magdagdag ng menu ng Permissions. Sa halip, magdagdag ng mga item ng menu sa Users at Settings menus.','Customize Permissions screen title for Groups'=>'I-customize ang pamagat ng screen ng Permissions para sa mga Grupo','Customize Permission Groups caption on user profile'=>'I-customize ang caption ng Permission Groups sa profile ng gumagamit','Only one group is selectable on Add User screen'=>'Isang grupo lamang ang maaaring piliin sa screen ng Magdagdag ng Gumagamit','Only one group is selectable on Edit User screen'=>'Isang grupo lamang ang maaaring piliin sa screen ng I-edit ang Gumagamit','Display a custom hint on Permissions > User Groups'=>'Ipakita ang isang pasaduring pahiwatig sa Mga Pahintulot > Mga Grupo ng Gumagamit','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Max na bilang ng mga non-hierarchical posts / terms na ipapakita sa isang pagkakataon (bawat pahina)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Max na bilang ng mga hiyarkikal na post / termino na ipapakita sa isang pagkakataon (bawat pahina)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'I-disable ang auto-determination ng kung gaano karaming mga antas ng puno ng pahina ang gagawing nakikita sa default. Sa halip, gumamit ng tinukoy na halaga.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Target na bilang ng mga nakikitang pahina/terms, na ginagamit para sa auto-determination ng bilang ng mga nakikitang antas','Make search function on the post selection metabox look at post content'=>'Gawing tingnan ng function ng paghahanap sa metabox ng pagpili ng post ang nilalaman ng post','Make search function on the post selection metabox look at post excerpt'=>'Gawing tingnan ng function ng paghahanap sa metabox ng pagpili ng post ang excerpt ng post','Search by last name instead of display name'=>'Maghanap ayon sa apelyido sa halip na display name','User field to search by default'=>'User field na hahanapin bilang default','User meta fields selectable for search (comma-separated)'=>'Mga user meta field na maaaring piliin para sa paghahanap (pinaghihiwalay ng kuwit)','User meta fields which should be treated as numeric (comma-separated)'=>'Mga user meta field na dapat ituring na numeriko (pinaghihiwalay ng kuwit)','User meta fields which should be treated as boolean (comma-separated)'=>'Mga user meta field na dapat ituring na boolean (pinaghihiwalay ng kuwit)','Use display name for search results instead of user_login'=>'Gumamit ng display name para sa mga resulta ng paghahanap sa halip na user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Kapag nagsasama-sama ng role metagroups sa kasalukuyang tinukoy na WP roles, huwag tanggalin ang mga grupo para sa mga naunang tinukoy na WP roles.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Pilitin ang pagtuklas ng WP user roles na dinagdag nang dinamikong ngunit hindi nakaimbak sa WP database.','To save memory on front end access, don\'t register any filters related to content editing'=>'Upang makatipid ng memorya sa pag-access sa front end, huwag magrehistro ng anumang filters na may kaugnayan sa pag-edit ng nilalaman','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Ang mga nakakabit na media ay walang anumang komento, kaya huwag magdagdag ng mga clause sa mga query ng komento para sa kanila','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Bawasan ang overhead ng query ng mga pahina (sa get_pages() at wp-admin) sa pamamagitan ng pag-default ng mga fields sa isang set list na hindi kasama ang post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Bawasan ang overhead ng wp-admin posts query sa pamamagitan ng pag-default ng mga fields sa isang set list na hindi kasama ang post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Bawasan ang overhead ng wp-admin Media query sa pamamagitan ng pag-default ng mga fields sa isang set list na hindi kasama ang post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Bawasan ang overhead ng wp-admin query para sa tinukoy na custom post type sa pamamagitan ng pag-default ng mga fields sa isang set list na hindi kasama ang post_content ','Work around database setup warnings (at plugin activation) on some servers'=>'Lutasin ang mga babala sa setup ng database (sa pag-activate ng plugin) sa ilang mga server','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Para sa paggamit sa pag-unlad lamang (nagsusupil sa post_status = \'publish\' clause para sa unfiltered post types na may anonymous user)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Para sa paggamit sa pag-unlad lamang (sa front end, huwag palitan ang \'post_status = \'publish\'\' clause na may filtered na katumbas)','Logged In'=>'Naka-log In','Not Logged In'=>'Hindi Naka-log In','Everyone'=>'Lahat','Change Request Notifications'=>'Mga Abiso ng Kahilingan sa Pagbabago','Submitted Revision Editors'=>'Isinumiteng Rebisyon','Scheduled Change Notifications'=>'Mga Nakatakdang Abiso ng Pagbabago','Scheduled Revision Monitors'=>'Mga Monitor ng Nakatakdang Rebisyon','Authenticated site users, except for Administrators'=>'Mga awtorisadong gumagamit ng site, maliban sa mga Administrator','Anonymous users (not logged in)'=>'Mga anonymous na gumagamit (hindi naka-log in)','All users (including anonymous)'=>'Lahat ng gumagamit (kasama a